  + '  label: string;\n'
  + '};\n'
  + '\n'
  + 'type OptionNonLeafNode<V extends string> = {\n'
  + '  label: string;\n'
  + '  children: Array<OptionNode<V>>;\n'
  + '};\n'
  + '\n'
  + 'type OptionNode<V extends string> = OptionLeafNode<V> | OptionNonLeafNode<V>;\n'
  + '\n'
  + 'type TreeSelectListProps<V extends string> = {\n'
  + '  ref?: Ref<HTMLDivElement>;\n'
  + '  className?: string;\n'
  + '  style: CSSProperties;\n'
  + '\n'
  + '  options: Array<OptionNode<V>>;\n'
