  + '  );\n'
  + '};\n'
  + '\n'
  + 'TreeSelectList.displayName = "TreeSelect.List";\n'
  + '\n'
  + 'type TreeSelectItemProps<V extends string> = {\n'
  + '  option: OptionNode<V>;\n'
  + '  internalValue?: V | null;\n'
