  + '\n'
  + '  return (\n'
  + '    <>\n'
  + '      <li className={classNames(styles.selectItem, stx)}>\n'
  + '        <button\n'
  + '          type="button"\n'
  + '          className={styles.selectItemButton}\n'
  + '          onClick={handleClick}\n'
  + '          onKeyDown={(e) => {\n'
  + '            if (e.key === "Enter" || e.key === " ") {\n'
  + '              e.preventDefault();\n'
  + '              handleClick();\n'
  + '            }\n'
  + '          }}\n'
  + '          tabIndex={0}\n'
  + '        >\n'
  + '          {!isLeaf && (\n'
  + '            <span\n'
  + '              className={styles.selectItemChevron}\n'
  + '              style={{ transform: isExpanded ? "rotate(90deg)" : "none" }}\n'
  + '            >\n'
  + '              <ChevronRight />\n'
  + '            </span>\n'
  + '          )}\n'
  + '          <span>{option.label}</span>\n'
  + '          {marked && <Check />}\n'
  + '        </button>\n'
  + '      </li>\n'
  + '      {!isLeaf &&\n'
  + '        isExpanded &&\n'
  + '        option.children.map((child, index) => (\n'
  + '          <TreeSelectItem\n'
  + '            key={"value" in child ? child.value : `group-${level}-${index}`}\n'
  + '            option={child}\n'
  + '            internalValue={internalValue}\n'
  + '            onItemClicked={onItemClicked}\n'
  + '            level={level + 1}\n'
  + '          />\n'
  + '        ))}\n'
  + '    </>\n'
  + '  );\n'
  + '};\n'
  + '\n'
  + 'export { TreeSelectList };\n'
